:root {
  --ps-blue: #0070ff;
  --ps-cyan: #39c6ff;
  --ps-deep: #030614;
  --gold: #ffc83d;
  --green: #35e08b;
  --orange: #ff9a3d;
  --red: #ff4057;
  --pink: #ff55b8;
  --purple: #a156ff;
  --white: #f4f7ff;
  --muted: #92a1c4;
  --glass: rgba(10, 20, 48, .58);
  --glass2: rgba(255, 255, 255, .07);
  --shadow: 0 18px 60px rgba(0, 0, 0, .45);
  --font-ui: "Segoe UI", "Trebuchet MS", Roboto, Arial, sans-serif;
  --font-display: "Arial Black", "Arial Narrow", Impact, "Segoe UI", sans-serif;
}
* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; height: 100%; overflow: hidden; background: #000; color: var(--white); font-family: var(--font-ui); user-select: none; -webkit-user-select: none; }
button, select, input { font-family: inherit; }
button { cursor: pointer; border: 0; color: inherit; }
.hidden { display: none !important; }
#app { position: fixed; inset: 0; overflow: hidden; background: #000; }
#game-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; opacity: 0; transition: opacity .9s ease; }
body.in-game #game-canvas { opacity: 1; }
body.brightness-low { filter: brightness(.72); }
body.brightness-high { filter: brightness(1.16); }

/* ================= PS5 SYSTEM ================= */
#ps5-layer { position: absolute; inset: 0; z-index: 20; overflow: hidden; background: #000; transition: opacity .7s ease, visibility .7s; }
#ps5-layer.off { opacity: 0; visibility: hidden; pointer-events: none; }
#space-bg { position: absolute; inset: 0; width: 100%; height: 100%; }
.ps5-vignette { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(circle at 50% 45%, transparent 35%, rgba(0, 0, 0, .55) 100%); }
.ps5-screen { position: absolute; inset: 0; display: none; opacity: 0; }
.ps5-screen.active { display: flex; opacity: 1; animation: screenIn .7s ease both; }
@keyframes screenIn { from { opacity: 0; transform: scale(1.015); } to { opacity: 1; transform: scale(1); } }

/* ---------- BOOT ---------- */
#boot-screen { align-items: center; justify-content: center; flex-direction: column; background: #000; overflow: hidden; }
.boot-halo { position: absolute; width: 90vw; height: 90vw; max-width: 1000px; max-height: 1000px; border-radius: 50%; background: radial-gradient(circle, rgba(40, 120, 255, .16) 0%, rgba(20, 60, 180, .04) 45%, transparent 70%); animation: haloPulse 4s ease-in-out infinite; }
@keyframes haloPulse { 0%, 100% { transform: scale(.92); opacity: .6; } 50% { transform: scale(1.06); opacity: 1; } }
.boot-logo { position: relative; display: flex; flex-direction: column; align-items: center; color: #fff; animation: logoIn 1.6s cubic-bezier(.2,.8,.2,1) both; }
@keyframes logoIn { from { opacity: 0; transform: scale(.86); filter: blur(12px); } to { opacity: 1; transform: scale(1); filter: blur(0); } }
.ps-shapes { width: 120px; height: 90px; color: rgba(140, 190, 255, .7); filter: drop-shadow(0 0 18px rgba(40, 130, 255, .7)); }
.ps5-word { font-family: var(--font-display); font-size: clamp(86px, 15vw, 210px); line-height: .82; letter-spacing: -8px; font-weight: 900; text-shadow: 0 0 12px #fff, 0 0 45px rgba(70, 150, 255, .95), 0 0 110px rgba(0, 80, 255, .8); }
.ps5-sub { font-size: clamp(11px, 1.4vw, 18px); letter-spacing: 10px; text-transform: uppercase; color: #cfe4ff; margin-top: 16px; }
.boot-progress { width: min(420px, 60vw); height: 3px; background: rgba(255, 255, 255, .12); margin-top: 52px; overflow: hidden; border-radius: 3px; opacity: 0; transition: opacity .3s; }
.boot-progress.show { opacity: 1; }
.boot-progress i { display: block; width: 0; height: 100%; background: linear-gradient(90deg, #fff, #54b9ff); box-shadow: 0 0 14px #3aa8ff; transition: width .4s ease; }
.boot-status { margin-top: 20px; font-size: 14px; letter-spacing: 2px; color: #c6d7f6; text-transform: uppercase; min-height: 20px; }
.boot-status b { color: #fff; background: rgba(255, 255, 255, .16); border-radius: 4px; padding: 1px 7px; }
.boot-hint { position: absolute; bottom: 34px; color: #60789e; font-size: 12px; letter-spacing: 2px; }
.power-btn { position: absolute; bottom: 80px; width: 64px; height: 64px; border-radius: 50%; border: 1px solid rgba(255, 255, 255, .22); background: rgba(255, 255, 255, .05); display: grid; place-items: center; transition: .25s; }
.power-btn:hover { background: rgba(70, 150, 255, .2); border-color: rgba(120, 190, 255, .8); box-shadow: 0 0 35px rgba(30, 130, 255, .45); transform: scale(1.06); }
.power-icon { width: 24px; height: 24px; border: 3px solid #eaf4ff; border-radius: 50%; border-top-color: transparent; position: relative; display: block; }
.power-icon:after { content: ""; position: absolute; left: 8px; top: -7px; width: 3px; height: 12px; background: #eaf4ff; border-radius: 2px; }

/* ---------- PROFILES ---------- */
#profile-screen { flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(circle at 50% 20%, #132b60 0%, #060d22 48%, #02040b 100%); padding: 28px 4vw; }
.profile-head { text-align: center; margin-bottom: 32px; }
.ps-badge { width: 48px; height: 48px; margin: 0 auto 12px; border-radius: 12px; background: linear-gradient(145deg, #e9f3ff, #8eb9e8); display: grid; place-items: center; box-shadow: 0 0 30px rgba(80, 160, 255, .4); }
.ps-badge-mark { font-family: var(--font-display); color: #0a1a38; font-size: 19px; letter-spacing: -1px; }
.profile-head h1 { font-size: clamp(26px, 3.2vw, 44px); margin: 0 0 7px; font-weight: 300; letter-spacing: .5px; }
.profile-head p { margin: 0; color: var(--muted); font-size: 14px; }
.profiles { display: flex; gap: clamp(12px, 2vw, 28px); justify-content: center; flex-wrap: wrap; max-width: 1100px; }
.profile-card { width: 205px; padding: 16px 16px 18px; border-radius: 20px; background: rgba(255, 255, 255, .055); border: 1px solid rgba(255, 255, 255, .09); display: flex; flex-direction: column; align-items: center; gap: 8px; transition: .25s; backdrop-filter: blur(14px); }
.profile-card:hover, .profile-card:focus-visible { background: rgba(255, 255, 255, .12); transform: translateY(-6px); border-color: rgba(110, 180, 255, .55); box-shadow: 0 22px 55px rgba(0, 0, 0, .45), 0 0 30px rgba(40, 130, 255, .14); outline: none; }
.profile-avatar { width: 112px; height: 112px; border-radius: 18px; overflow: hidden; box-shadow: 0 10px 30px rgba(0,0,0,.35); display: grid; place-items: center; }
.profile-avatar svg { width: 100%; height: 100%; display: block; }
.profile-avatar.plus { font-size: 52px; font-weight: 200; background: rgba(255, 255, 255, .08); border: 2px dashed rgba(255, 255, 255, .28); color: #bcd2f7; }
.profile-name { font-size: 14px; font-weight: 700; letter-spacing: 1.5px; margin-top: 4px; }
.profile-meta { font-size: 11px; color: #90a7ca; }
.profile-tag { font-size: 9px; letter-spacing: 2px; color: #6e8ab4; border: 1px solid rgba(255,255,255,.12); padding: 3px 9px; border-radius: 20px; }
.profile-card.create .profile-name { font-size: 12px; }
.profile-footer { position: absolute; bottom: 22px; width: 100%; display: flex; justify-content: center; align-items: center; gap: 28px; font-size: 12px; color: #6980a5; }
.ghost-btn { background: none; border: 1px solid rgba(255,255,255,.14); color: #9db0cf; border-radius: 20px; padding: 7px 16px; font-size: 11px; letter-spacing: 1px; }
.connect-hint { color: #5c7398; }

/* ---------- DASHBOARD ---------- */
#dashboard { flex-direction: column; background: radial-gradient(ellipse at 70% 15%, rgba(20, 63, 130, .5), transparent 50%), radial-gradient(ellipse at 25% 80%, rgba(60, 20, 100, .28), transparent 55%), linear-gradient(155deg, #07142c 0%, #030817 45%, #010208 100%); overflow: hidden; }
.dash-nebula { position: absolute; inset: -20%; background: radial-gradient(ellipse at 68% 28%, rgba(0, 120, 255, .2), transparent 30%), radial-gradient(ellipse at 32% 65%, rgba(115, 50, 255, .16), transparent 28%), radial-gradient(ellipse at 82% 72%, rgba(255, 70, 120, .08), transparent 22%); filter: blur(20px); animation: nebulaMove 18s ease-in-out infinite alternate; }
@keyframes nebulaMove { from { transform: translate(-2%, -1%) scale(1); } to { transform: translate(2%, 1%) scale(1.08); } }
.dash-particles { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.dash-particles i { position: absolute; width: 3px; height: 3px; border-radius: 50%; background: #78c7ff; box-shadow: 0 0 9px #46a8ff; opacity: .45; animation: floatParticle linear infinite; }
@keyframes floatParticle { from { transform: translateY(20px); } to { transform: translateY(-80px); } }
.dash-top { position: relative; z-index: 4; display: flex; justify-content: space-between; align-items: center; padding: 22px 34px 10px; }
.dash-user { display: flex; align-items: center; gap: 12px; }
.dash-avatar { width: 46px; height: 46px; border-radius: 50%; background: linear-gradient(145deg, #ff9846, #8f34ff); display: grid; place-items: center; font-weight: 800; font-size: 20px; border: 2px solid rgba(255,255,255,.4); box-shadow: 0 0 20px rgba(100, 140, 255, .3); }
