.ps5-modal.open { display: flex; animation: fadeIn .22s ease; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.modal-panel { position: relative; width: min(1120px, 94vw); max-height: 90vh; overflow: auto; background: linear-gradient(145deg, rgba(19, 34, 70, .95), rgba(5, 10, 26, .98)); border: 1px solid rgba(120, 170, 255, .2); border-radius: 24px; padding: 32px 36px; box-shadow: var(--shadow); }
.modal-close { position: absolute; right: 20px; top: 16px; width: 34px; height: 34px; border-radius: 50%; background: rgba(255,255,255,.08); font-size: 16px; z-index: 2; }
