.store-price { font-size: 12px; color: #9be2ff; font-weight: 700; }
.buy-btn { width: 100%; margin-top: 8px; border-radius: 8px; padding: 8px; background: rgba(80, 160, 255, .18); border: 1px solid rgba(100, 180, 255, .35); color: #c8e9ff; font-size: 10px; letter-spacing: 1px; }
.buy-btn:hover { background: rgba(80, 160, 255, .32); }
.buy-btn.done { background: rgba(60, 220, 140, .12); border-color: rgba(60, 220, 140, .35); color: #79ffbc; }
.dl-bar { height: 5px; border-radius: 5px; background: rgba(255,255,255,.1); overflow: hidden; margin-top: 8px; }
.dl-bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, #50b8ff, #b6f0ff); }
.dl-txt { font-size: 8px; color: #76a5d4; margin-top: 4px; }
.trophy-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 14px; }
.trophy-card { background: rgba(255,255,255,.045); border: 1px solid rgba(255,255,255,.08); border-radius: 14px; padding: 18px; text-align: center; }
.trophy-medal { width: 64px; height: 64px; border-radius: 50%; margin: 0 auto 12px; display: grid; place-items: center; font-size: 30px; border: 3px solid; box-shadow: 0 0 25px currentColor; }
.trophy-card h4 { margin: 0 0 4px; font-size: 13px; }
.trophy-card p { margin: 0; font-size: 10px; color: #859bbd; }
.friend-row { display: flex; align-items: center; gap: 12px; padding: 10px 4px; border-bottom: 1px solid rgba(255,255,255,.06); }
.friend-avatar { width: 38px; height: 38px; border-radius: 50%; background: linear-gradient(145deg, var(--c1), var(--c2)); display: grid; place-items: center; font-weight: 700; font-size: 14px; }
.friend-info { flex: 1; }
.friend-info b { font-size: 12px; display: block; }
.friend-info span { font-size: 9px; color: #7f97bb; }
.friend-status { font-size: 9px; color: #63ef9c; }
.friend-status.off { color: #687d9e; }
.invite-btn { background: rgba(80, 160, 255, .16); border: 1px solid rgba(100, 180, 255, .3); border-radius: 6px; padding: 5px 10px; font-size: 9px; }
.settings-list label { display: flex; justify-content: space-between; align-items: center; padding: 14px 2px; border-bottom: 1px solid rgba(255,255,255,.06); font-size: 12px; color: #c8d7f0; gap: 20px; }
.settings-list select, .settings-list input[type=range] { width: 210px; accent-color: #4ba6ff; background: rgba(255,255,255,.08); color: #fff; border: 1px solid rgba(255,255,255,.12); border-radius: 6px; padding: 6px 8px; }
.search-box { display: flex; gap: 10px; margin-bottom: 22px; }
.search-box input { flex: 1; background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.15); border-radius: 30px; padding: 12px 20px; color: #fff; font-size: 14px; outline: none; }
.search-box input:focus { border-color: #5cb4ff; box-shadow: 0 0 0 3px rgba(80,160,255,.15); }
.search-results { color: #8ba3c7; font-size: 12px; line-height: 2; }
.sleep-screen { position: absolute; inset: 0; z-index: 40; display: none; flex-direction: column; align-items: center; justify-content: center; background: #000; text-align: center; }
.sleep-screen.open { display: flex; }
.sleep-moon { font-size: 80px; color: #3b5a8f; margin-bottom: 12px; }
.sleep-screen h2 { letter-spacing: 8px; font-weight: 300; font-size: 20px; color: #7997c4; }
.sleep-screen p { color: #4e6488; font-size: 12px; }
.sleep-screen .power-btn { position: relative; bottom: auto; margin-top: 24px; }
.power-btn.small { width: 52px; height: 52px; }

/* ================= GAME ================= */
#game-ui { position: absolute; inset: 0; z-index: 10; pointer-events: none; font-family: var(--font-ui); }
#game-ui > * { pointer-events: none; }
#game-ui button, #game-ui input, #game-ui select, #game-ui .game-overlay, #game-ui .ps5-modal { pointer-events: auto; }
#hud-top { position: absolute; top: max(10px, env(safe-area-inset-top)); left: 12px; right: 12px; display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; z-index: 6; }
.hud-player { display: flex; align-items: center; gap: 9px; background: linear-gradient(90deg, rgba(4,10,20,.72), rgba(4,10,20,.18)); border: 1px solid rgba(255,255,255,.13); padding: 7px 12px 7px 7px; border-radius: 12px; backdrop-filter: blur(6px); }
.hud-avatar { width: 34px; height: 34px; border-radius: 50%; background: linear-gradient(145deg, #ff9b45, #7c2eff); display: grid; place-items: center; font-weight: 800; font-size: 14px; border: 1px solid rgba(255,255,255,.5); }
.hud-bars { display: flex; flex-direction: column; gap: 3px; }
.bar-row { display: flex; align-items: center; gap: 4px; }
.bar-ico { font-size: 8px; width: 10px; text-align: center; }
.bar { width: 88px; height: 5px; border-radius: 4px; background: rgba(0,0,0,.5); overflow: hidden; }
.bar i { display: block; height: 100%; background: linear-gradient(90deg, #21b965, #7cff9d); border-radius: 4px; transition: width .25s; }
.bar.hunger i { background: linear-gradient(90deg, #d77b19, #ffc15d); }
.bar.thirst i { background: linear-gradient(90deg, #1a7fd4, #63d1ff); }
.hud-center { display: flex; flex-direction: column; align-items: center; gap: 2px; margin-top: 1px; text-shadow: 0 2px 8px #000; }
.hud-clock { font-size: 17px; font-weight: 700; letter-spacing: 2px; }
.wanted { display: flex; gap: 2px; min-height: 13px; }
.wanted span { color: rgba(255,255,255,.18); font-size: 12px; text-shadow: 0 0 6px rgba(0,0,0,.8); }
.wanted span.on { color: #ffd23c; text-shadow: 0 0 10px #ffae00; animation: starPulse .8s infinite alternate; }
@keyframes starPulse { to { transform: scale(1.15); } }
.hud-money { color: #7dffab; font-size: 14px; font-weight: 800; letter-spacing: .5px; }
.hud-actions { display: flex; gap: 5px; }
.hud-icon { width: 32px; height: 32px; border-radius: 8px; background: rgba(5,10,20,.55); border: 1px solid rgba(255,255,255,.15); color: #d9e7ff; font-size: 13px; backdrop-filter: blur(6px); }
.hud-icon:hover { background: rgba(60,140,255,.3); }
.hud-weather { position: absolute; right: 12px; top: 46px; font-size: 9px; letter-spacing: 1px; color: #d6e6ff; background: rgba(5,10,20,.45); border: 1px solid rgba(255,255,255,.1); padding: 4px 8px; border-radius: 20px; }
#minimap-wrap { position: absolute; top: 78px; right: 14px; width: 164px; height: 164px; z-index: 5; }
#minimap { width: 164px; height: 164px; border-radius: 50%; border: 2px solid rgba(255,255,255,.45); box-shadow: 0 4px 22px rgba(0,0,0,.65), inset 0 0 25px rgba(0,0,0,.5); background: #0a141a; }
.mm-n { position: absolute; top: -4px; left: 50%; transform: translateX(-50%); background: #fff; color: #111; font-size: 8px; font-weight: 900; width: 15px; height: 15px; border-radius: 50%; display: grid; place-items: center; box-shadow: 0 1px 4px #000; }
.mm-ring { position: absolute; inset: 0; border-radius: 50%; border: 1px solid rgba(120, 190, 255, .35); pointer-events: none; }
.mm-district { position: absolute; left: 50%; bottom: 8px; transform: translateX(-50%); font-size: 7px; letter-spacing: 1px; background: rgba(0,0,0,.55); padding: 2px 7px; border-radius: 10px; color: #cfe3ff; white-space: nowrap; }
.mm-gps { position: absolute; right: -2px; bottom: -4px; background: rgba(4,10,20,.8); border: 1px solid rgba(100,180,255,.25); font-size: 7px; padding: 3px 6px; border-radius: 8px; color: #7fb7ff; }
.mm-gps b { color: #fff; }
#mission-hud { position: absolute; left: 14px; top: 74px; width: min(300px, 32vw); background: linear-gradient(100deg, rgba(4,10,20,.78), rgba(4,10,20,.25)); border-left: 3px solid #ffd23c; border-radius: 4px 10px 10px 4px; padding: 8px 12px; backdrop-filter: blur(5px); z-index: 5; }
.mission-label { font-size: 7px; letter-spacing: 2px; color: #ffd23c; }
.mission-name { font-size: 15px; font-weight: 800; margin: 1px 0 3px; text-transform: uppercase; letter-spacing: .3px; }
.mission-objective { font-size: 10px; color: #c8d6ea; line-height: 1.3; }
.mission-reward { font-size: 8px; color: #7dffab; margin-top: 3px; }
#vehicle-hud { position: absolute; bottom: 18px; left: 50%; transform: translateX(-50%); width: min(390px, 44vw); z-index: 5; background: linear-gradient(180deg, rgba(3,8,18,.28), rgba(3,8,18,.8)); border: 1px solid rgba(255,255,255,.12); border-radius: 14px 14px 0 0; padding: 9px 16px 7px; backdrop-filter: blur(5px); display: flex; align-items: center; gap: 12px; }
.speedo { display: flex; align-items: baseline; gap: 2px; min-width: 78px; }
.speedo b { font-size: 30px; font-family: var(--font-display); letter-spacing: -1px; color: #fff; text-shadow: 0 0 14px rgba(80,170,255,.5); }
.speedo span { font-size: 8px; color: #7da3cf; }
.gear { display: flex; flex-direction: column; align-items: center; border-left: 1px solid rgba(255,255,255,.12); padding-left: 10px; }
.gear span { font-size: 6px; color: #6e8ab0; letter-spacing: 1px; }
.gear b { font-size: 19px; color: #ffcf58; }
.rpm { flex: 1; height: 5px; border-radius: 3px; background: rgba(255,255,255,.1); overflow: hidden; }
.rpm i { display: block; height: 100%; width: 20%; background: linear-gradient(90deg, #55ff9d, #ffe24e 65%, #ff4747); }
.fuel { position: absolute; right: 14px; top: 7px; display: flex; align-items: center; gap: 4px; font-size: 8px; color: #a9c2df; }
.fuel div { width: 46px; height: 4px; background: rgba(255,255,255,.12); border-radius: 3px; overflow: hidden; }
.fuel i { display: block; height: 100%; width: 100%; background: #ffb236; }
.car-name { position: absolute; left: 16px; bottom: 1px; font-size: 6px; letter-spacing: 1.5px; color: #7b98bc; }
#interaction { position: absolute; left: 50%; bottom: 22%; transform: translateX(-50%); background: rgba(5,10,20,.8); border: 1px solid rgba(255,255,255,.2); padding: 8px 16px; border-radius: 10px; font-size: 12px; display: flex; gap: 9px; align-items: center; backdrop-filter: blur(6px); z-index: 7; white-space: nowrap; }
#interaction kbd { background: #fff; color: #061020; border-radius: 4px; width: 22px; height: 22px; display: grid; place-items: center; font-weight: 800; font-size: 11px; }
#subtitle { position: absolute; bottom: 13%; left: 50%; transform: translateX(-50%); max-width: 60vw; text-align: center; background: rgba(0,0,0,.65); padding: 6px 14px; border-radius: 6px; font-size: 11px; color: #f2f7ff; display: none; z-index: 7; }
#notifications { position: absolute; top: 12%; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 5px; z-index: 8; }
.notif { background: linear-gradient(90deg, rgba(5,12,26,.9), rgba(12,32,62,.82)); border: 1px solid rgba(120,180,255,.3); padding: 7px 18px; border-radius: 20px; font-size: 10px; letter-spacing: .5px; animation: notifIn .3s ease both, notifOut .4s 3s ease forwards; color: #eaf5ff; box-shadow: 0 8px 24px rgba(0,0,0,.4); }
@keyframes notifIn { from { opacity: 0; transform: translateY(-8px); } }
@keyframes notifOut { to { opacity: 0; transform: translateY(-8px); } }
#toast { position: absolute; left: 50%; bottom: 33%; transform: translateX(-50%); background: #eef7ff; color: #071126; border-radius: 8px; padding: 8px 18px; font-size: 11px; font-weight: 700; z-index: 30; display: none; box-shadow: 0 10px 30px rgba(0,0,0,.5); }
#mission-marker { position: absolute; z-index: 4; pointer-events: none; transform: translate(-50%, -100%); }
.marker-beam { width: 38px; height: 60px; background: linear-gradient(180deg, rgba(255,210,60,0), rgba(255,210,60,.55)); clip-path: polygon(50% 0, 100% 100%, 0 100%); animation: beamPulse 1.5s ease-in-out infinite; }
.marker-icon { position: absolute; left: 50%; top: -23px; transform: translateX(-50%); width: 28px; height: 28px; border-radius: 50%; background: #ffd23c; color: #1a1400; font-weight: 900; display: grid; place-items: center; box-shadow: 0 0 20px rgba(255,210,60,.9); }
.marker-dist { position: absolute; top: 4px; left: 50%; transform: translateX(-50%); font-size: 8px; color: #fff; text-shadow: 0 1px 4px #000; white-space: nowrap; }
@keyframes beamPulse { 50% { opacity: .45; transform: scaleY(1.08); } }

/* ================= VIRTUAL CONTROLS ================= */
#virtual-controls { position: absolute; inset: 0; z-index: 8; pointer-events: none; touch-action: none; }
#virtual-controls > div { pointer-events: auto; }
.vc-gta { display: none; }
.mode-gta .vc-gta { display: block; }
.vc-gta-left { position: absolute; left: 14px; bottom: max(12px, env(safe-area-inset-bottom)); width: 270px; height: 270px; }
.vc-gta-right { position: absolute; right: 14px; bottom: max(12px, env(safe-area-inset-bottom)); width: 290px; height: 300px; }
.shoulder-row { position: absolute; top: 0; left: 0; display: flex; gap: 8px; }
.shoulder-row.right { right: 0; left: auto; }
.vc-pill { min-width: 64px; height: 32px; border-radius: 18px; background: rgba(235, 244, 255, .82); color: #0a1222; border: 1px solid rgba(255,255,255,.9); font-size: 12px; font-weight: 900; box-shadow: 0 3px 10px rgba(0,0,0,.45); display: flex; flex-direction: column; align-items: center; justify-content: center; line-height: 1; }
.vc-pill small { font-size: 5px; letter-spacing: .3px; font-weight: 700; margin-top: 2px; }
.vc-pill.trigger { background: rgba(220, 232, 247, .65); min-width: 86px; border-radius: 12px; }
.vc-pill.active, .vc-pill:active { background: #59b8ff; color: #001428; box-shadow: 0 0 22px #3aa8ff; }
.dpad { position: absolute; left: 14px; top: 40px; width: 78px; height: 78px; display: grid; grid-template-columns: repeat(3, 1fr); grid-template-rows: repeat(3, 1fr); gap: 2px; }
.dpad button { background: rgba(232,242,255,.7); color: #101b30; border-radius: 5px; font-size: 9px; display: grid; place-items: center; border: 1px solid rgba(255,255,255,.7); }
.dpad button:nth-child(1) { grid-column: 2; grid-row: 1; }
.dpad button:nth-child(2) { grid-column: 1; grid-row: 2; }
.dpad button:nth-child(3) { grid-column: 3; grid-row: 2; }
.dpad button:nth-child(4) { grid-column: 2; grid-row: 3; }
.stick-zone { position: absolute; width: 128px; height: 128px; border-radius: 50%; border: 2px solid rgba(255,255,255,.7); background: radial-gradient(circle, rgba(6,12,24,.32), rgba(8,15,30,.6)); touch-action: none; box-shadow: 0 5px 20px rgba(0,0,0,.3), inset 0 0 20px rgba(0,0,0,.25); }
.left-stick { left: 74px; bottom: 28px; }
.right-stick { right: 80px; bottom: 40px; }
.stick-ring { position: absolute; inset: 15px; border-radius: 50%; border: 1px dashed rgba(255,255,255,.22); }
.stick-knob { position: absolute; width: 56px; height: 56px; left: 50%; top: 50%; transform: translate(-50%,-50%); border-radius: 50%; background: radial-gradient(circle at 38% 32%, #6b7d99, #0a111f 72%); border: 2px solid rgba(255,255,255,.65); box-shadow: 0 4px 12px rgba(0,0,0,.55); transition: transform .05s linear; }
.stick-label { position: absolute; left: 50%; top: 50%; transform: translate(-50%,-50%); font-size: 10px; font-weight: 800; letter-spacing: 1px; color: rgba(255,255,255,.8); pointer-events: none; z-index: 2; }
.stick-hint { position: absolute; left: 50%; bottom: -16px; transform: translateX(-50%); font-size: 6px; letter-spacing: .6px; color: rgba(255,255,255,.65); white-space: nowrap; }
.mini-actions { position: absolute; left: 0; bottom: 0; display: flex; gap: 5px; flex-wrap: wrap; width: 66px; }
.mini-actions.right { left: auto; right: 0; width: 72px; justify-content: flex-end; }
.mini-actions button { min-width: 29px; height: 22px; border-radius: 5px; background: rgba(5,12,25,.62); border: 1px solid rgba(255,255,255,.3); color: #dbe9ff; font-size: 6px; padding: 1px 4px; line-height: 1; }
.mini-actions button:active { background: #51b3ff; color: #00111f; }
.action-cluster { position: absolute; right: 118px; top: 58px; width: 110px; height: 110px; }
.face { position: absolute; width: 48px; height: 48px; border-radius: 50%; border: 2px solid rgba(255,255,255,.7); font-size: 17px; font-weight: 900; display: flex; flex-direction: column; align-items: center; justify-content: center; line-height: 1; box-shadow: 0 3px 12px rgba(0,0,0,.5); }
.face small { font-size: 4px; letter-spacing: .3px; font-weight: 700; margin-top: 2px; }
.face.tri { left: 31px; top: 0; background: rgba(31, 209, 132, .78); }
.face.sq { right: 0; top: 31px; background: rgba(255, 83, 181, .8); }
.face.cir { left: 31px; bottom: 0; background: rgba(255, 62, 78, .82); }
.face.cross { left: 0; top: 31px; background: rgba(48, 137, 255, .82); }
.face.active { filter: brightness(1.6); box-shadow: 0 0 24px currentColor; }
.face.tri.active { color: #25ff9c; }
.face.sq.active { color: #ff55b8; }
.face.cir.active { color: #ff4555; }
.face.cross.active { color: #4ca4ff; }

/* Tutorial mode */
