.tutorial-title { position: absolute; top: 16%; left: 50%; transform: translateX(-50%); font-size: 12px; letter-spacing: 4px; color: #fff; background: linear-gradient(90deg, rgba(100,40,180,.8), rgba(255,100,30,.8)); padding: 8px 20px; border-radius: 20px; }
.tutorial-step { position: absolute; border: 2px dashed; border-radius: 22px; padding: 14px; font-size: 10px; font-weight: 800; letter-spacing: 1px; text-align: center; text-shadow: 0 2px 8px #000; backdrop-filter: blur(2px); }
.tutorial-step b { display: inline-grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; background: #fff; color: #222; margin-right: 6px; }
