.step-2 { right: 7vw; bottom: 25vh; width: 250px; height: 160px; border-color: #d066ff; color: #ecc8ff; background: rgba(80, 20, 100, .18); }
.step-3 { right: 24vw; bottom: 9vh; width: 240px; border-color: #ffb14f; color: #ffe0b0; background: rgba(110, 50, 10, .15); }
.step-4 { left: 32vw; bottom: 9vh; width: 190px; border-color: #5ec8ff; color: #c2edff; background: rgba(10, 60, 100, .15); }
#tutorialClose { position: absolute; left: 50%; top: 70%; transform: translateX(-50%); background: #fff; color: #1a1230; border-radius: 30px; padding: 10px 26px; font-weight: 800; font-size: 11px; letter-spacing: 1px; pointer-events: auto; box-shadow: 0 8px 28px rgba(0,0,0,.45); }
.mode-tutorial .vc-gta-left, .mode-tutorial .vc-gta-right { display: block !important; }
.mode-tutorial .vc-gta { display: block; }
.mode-tutorial .stick-zone { border-width: 3px; box-shadow: 0 0 30px rgba(80, 255, 160, .25); }
.mode-tutorial .right-stick { box-shadow: 0 0 30px rgba(200, 80, 255, .25); }

/* DualSense mode */
#dualsense-wrap { display: none; position: absolute; bottom: -8px; left: 50%; transform: translateX(-50%); z-index: 9; width: min(760px, 88vw); }
