.ds-dpad { position: absolute; left: 2px; top: 8px; width: 76px; height: 76px; display: grid; grid-template-columns: repeat(3, 1fr); grid-template-rows: repeat(3, 1fr); gap: 2px; }
.ds-dpad button { background: linear-gradient(180deg, #424957, #1d222c); color: #dbe3ef; border-radius: 5px; font-size: 9px; border: 1px solid rgba(255,255,255,.22); }
