.ds-stick { position: absolute; width: 58px; height: 58px; border-radius: 50%; background: radial-gradient(circle at 38% 30%, #4b5261, #151922 70%); border: 3px solid #d8dee8; box-shadow: 0 3px 8px rgba(0,0,0,.45), inset 0 0 12px rgba(0,0,0,.5); }
