    if (Math.abs(x) < 26 || Math.abs(z) < 26) return true;
    for (const r of reserved) {
      if (Math.abs(x - r.x) < (ww + r.ww) / 2 + 8 && Math.abs(z - r.z) < (dd + r.dd) / 2 + 8) return true;
    }
    return false;
  };

  // Landmarks do Centro
