  w.addSign('AEROPORTO INTERNACIONAL', 160, 11, z + 99.2, 0, 50, 5, { bg: '#092640', color: '#d9f3ff', border: '#56c8ff', font: 'bold 58px Arial', sub: 'CIDADE CAIO · BRASIL', subColor: '#9fe5ff' });
