  const tower = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(2.2, 3, 34, 8), mat(0xb7c1c7, { roughness: .6 }));
  shaft.position.y = 17; shaft.castShadow = true; tower.add(shaft);
