    bag.position.set(rand(110, 200), .35, rand(-360, -320)); bag.rotation.y = rand(0, 3); bag.castShadow = true; w.scene.add(bag);
  }

  // luzes da pista
  const lights = [];
  for (let zz = -740; zz <= -260; zz += 22) {
