279:   enterNearestCar() {
280:     const p = this.player;
281:     const traffic = this.world.traffic.nearest(p.position.x, p.position.z, 7);
282:     const ownDist = Math.hypot(this.car.position.x - p.position.x, this.car.position.z - p.position.z);
283:     if (traffic && traffic.dist < (ownDist < 7 ? ownDist : 999)) {
284:       this.world.traffic.hide(traffic.index);
285:       this.currentTrafficIndex = traffic.index;
286:       this.car.position.set(traffic.x, 0, traffic.z);
287:       this.car.heading = traffic.axis === 'x' ? (traffic.dir > 0 ? Math.PI / 2 : -Math.PI / 2) : (traffic.dir > 0 ? 0 : Math.PI);
288:       this.car.setColor(traffic.color);
289:       this.car.name = 'CARRO DE RUA';
290:       this.car.fuel = Math.max(30, Math.random() * 90);
291:       this.car.repair();
292:     } else if (ownDist < 7.5) {
293:       this.car.group.visible = true;
294:     } else {
295:       this.notify('Nenhum carro por perto. Aproxime-se de um veículo.');
296:       return;
297:     }
298:     p.inCar = true;
299:     p.root.visible = false;
300:     this.car.enter();
301:     this.car.group.visible = true;
302:     this.audio.carDoor();
303:     this.notify(`Entrou no ${this.car.name}. R2 acelera · E sai.`);
