332:     const poi = this.world.nearestPOI(this.player.position.x, this.player.position.z);
333:     const ownDist = Math.hypot(this.car.position.x - this.player.position.x, this.car.position.z - this.player.position.z);
334:     const traffic = this.world.traffic.nearest(this.player.position.x, this.player.position.z, 7);
335:     if (poi) { this.openShop(poi.type === 'food' ? 'food' : poi.type); return; }
336:     if (traffic) { this.enterNearestCar(); return; }
337:     if (ownDist < 7.5) { this.enterNearestCar(); return; }
338:     this.notify('Nada para interagir por aqui.');
