356:       const poi = this.world.nearestPOI(p.position.x, p.position.z);
357:       const traffic = this.world.traffic.nearest(p.position.x, p.position.z, 7);
358:       const ownDist = Math.hypot(this.car.position.x - p.position.x, this.car.position.z - p.position.z);
359:       if (poi) {
360:         const names = { clothing: 'Entrar na Loja de Roupas', barber: 'Entrar na Barbearia', gym: 'Entrar na Academia', gun: 'Entrar na Ammu-Nation', mechanic: 'Entrar na Mecânica', gas: 'Abastecer', house: 'Entrar em Casa', food: 'Comprar na Lanchonete', jewelry: 'Entrar na Joalheria', hospital: 'Atendimento no Hospital' };
361:         text = names[poi.type] || 'Interagir';
362:       } else if (traffic) text = 'Entrar no carro';
363:       else if (ownDist < 7.5) text = `Entrar no ${this.car.name}`;
