375:   attack() {
376:     if (this.dead || this.paused) return;
377:     const p = this.player;
378:     if (p.inCar) { this.horn(); return; }
379:     if (p.shootCooldown > 0) return;
380:     const w = WEAPONS[p.weapon];
381:     p.shootCooldown = w.rate;
382:     if (w.ammo !== Infinity) {
383:       if (!p.ammo[p.weapon]) { this.audio.uiError(); this.notify('Munição acabou! Compre na Ammu-Nation.'); return; }
384:       p.ammo[p.weapon]--;
385:     }
386:     if (['soco', 'taco', 'faca'].includes(p.weapon)) this.melee(w);
387:     else this.fireWeapon(w);
388:   }
389: 
390:   melee(w) {
391:     const p = this.player;
392:     this.audio.punch();
393:     if (navigator.vibrate && this.settings.vibration) navigator.vibrate(25);
394:     const dir = new THREE.Vector3(Math.sin(p.yaw), 0, Math.cos(p.yaw));
395:     const targetPoint = p.position.clone().add(dir.multiplyScalar(1.4));
396:     const enemies = this.missions.enemies.filter(e => !e.dead && e.position.distanceTo(targetPoint) < w.range);
397:     if (enemies.length) { enemies[0].hit(w.damage); this.notify('Acertou o inimigo!'); this.police.setWanted(p.wanted + .5); return; }
398:     const peds = this.world.peds.nearby(targetPoint.x, targetPoint.z, w.range);
399:     if (peds.length) { this.onPedHit(peds[0]); this.notify('Você acertou um pedestre!'); return; }
400:     this.spawnHitEffect(targetPoint, 0xffe0a0);
401:   }
402: 
403:   fireWeapon(w) {
404:     const p = this.player;
405:     this.audio[w.sound === 'explosion' ? 'explosion' : 'gunshot']();
406:     if (navigator.vibrate && this.settings.vibration) navigator.vibrate(w.auto ? 12 : 35);
407:     const dir = new THREE.Vector3();
408:     this.camera.getWorldDirection(dir);
409:     if (!p.aiming && !p.inCar) {
410:       dir.set(Math.sin(p.yaw), 0, Math.cos(p.yaw));
411:       if (this.camPitch) dir.y = -.02;
412:       dir.normalize();
413:     }
414:     const origin = p.position.clone().add(new THREE.Vector3(0, 1.45, 0));
415:     this.muzzleFlash(origin.clone().add(dir.clone().multiplyScalar(.8)), dir);
416:     this.shake = Math.max(this.shake, .08);
417:     this.police.setWanted(p.wanted + .5);
418: 
419:     let best = null, bestDist = w.range;
420:     for (const e of this.missions.enemies) {
421:       if (e.dead) continue;
422:       const to = e.position.clone().add(new THREE.Vector3(0, 1.1, 0)).sub(origin);
423:       const proj = to.dot(dir);
424:       if (proj < 0 || proj > w.range) continue;
425:       const perp = to.clone().sub(dir.clone().multiplyScalar(proj)).length();
426:       if (perp < 1.1 && proj < bestDist) { best = e; bestDist = proj; }
427:     }
428:     if (!best) {
429:       const peds = this.world.peds.nearby(p.position.x, p.position.z, Math.min(w.range, 60));
430:       let pedBest = null, pedDist = bestDist;
431:       for (const ped of peds) {
432:         const to = new THREE.Vector3(ped.x, .9, ped.z).sub(origin);
433:         const proj = to.dot(dir);
434:         if (proj < 0 || proj > w.range) continue;
435:         const perp = to.clone().sub(dir.clone().multiplyScalar(proj)).length();
436:         if (perp < .8 && proj < pedDist) { pedBest = ped; pedDist = proj; }
437:       }
438:       if (pedBest) {
439:         this.onPedHit(pedBest);
440:         this.spawnHitEffect(new THREE.Vector3(pedBest.x, 1, pedBest.z), 0xff4455);
441:         return;
442:       }
443:     }
444:     if (best) {
445:       best.hit(w.damage);
446:       this.spawnHitEffect(best.position.clone().add(new THREE.Vector3(0, 1.1, 0)), 0xff3344);
447:       this.notify('Alvo atingido!');
448:       this.police.setWanted(p.wanted + .5);
449:     } else {
450:       const end = origin.clone().add(dir.clone().multiplyScalar(Math.min(w.range, 60)));
451:       this.tracer(origin, end);
452:       this.spawnHitEffect(end, 0xffcf7a);
453:     }
454:     if (['bazuca', 'rpg', 'granada', 'molotov'].includes(p.weapon)) {
455:       const end = origin.clone().add(dir.clone().multiplyScalar(18));
456:       this.spawnExplosion(end, 1.4);
457:       this.police.setWanted(p.wanted + 1);
458:     }
459:   }
460: 
461:   spawnHitEffect(pos, color) {
462:     const geo = new THREE.SphereGeometry(.11, 5, 4);
463:     const mat = new THREE.MeshBasicMaterial({ color });
464:     const m = new THREE.Mesh(geo, mat);
465:     m.position.copy(pos); this.scene.add(m);
466:     setTimeout(() => { this.scene.remove(m); geo.dispose(); mat.dispose(); }, 130);
467:   }
468: 
469:   tracer(a, b) {
470:     const geo = new THREE.BufferGeometry().setFromPoints([a, b]);
471:     const mat = new THREE.LineBasicMaterial({ color: 0xffe29a, transparent: true, opacity: .8 });
472:     const line = new THREE.Line(geo, mat);
