179:   updateMarker() {
180:     const g = this.game;
181:     const marker = $('#mission-marker');
182:     const target = g.missions.target;
183:     if (!target || !g.missions.active) { marker.classList.add('hidden'); return; }
184:     const v = new THREE.Vector3(target.x, 3.2, target.z);
185:     const cam = g.camera;
186:     const dist = v.distanceTo(cam.position);
187:     v.project(cam);
188:     if (v.z > 1 || v.x < -1.2 || v.x > 1.2 || v.y < -1.2 || v.y > 1.2) { marker.classList.add('hidden'); return; }
189:     marker.classList.remove('hidden');
190:     const x = (v.x * .5 + .5) * innerWidth;
191:     const y = (-v.y * .5 + .5) * innerHeight;
192:     marker.style.left = x + 'px';
193:     marker.style.top = y + 'px';
194:     marker.querySelector('.marker-dist').textContent = Math.round(dist) + ' m';
195:   }
