197:   drawMinimap() {
198:     const c = $('#minimap');
199:     if (!c) return;
200:     const ctx = c.getContext('2d');
201:     const W = c.width, H = c.height;
202:     const g = this.game, p = g.player, w = g.world;
203:     const px = p.inCar ? g.car.position.x : p.position.x;
204:     const pz = p.inCar ? g.car.position.z : p.position.z;
205:     const scale = 1.35;
206:     const toX = x => W / 2 + (x - px) * scale;
207:     const toY = z => H / 2 + (z - pz) * scale;
208:     ctx.clearRect(0, 0, W, H);
209:     ctx.save();
210:     ctx.beginPath(); ctx.arc(W / 2, H / 2, W / 2, 0, Math.PI * 2); ctx.clip();
211:     ctx.fillStyle = '#1d3028'; ctx.fillRect(0, 0, W, H);
212:     // distritos
213:     for (const d of w.districts) {
214:       const x = toX(d.x), y = toY(d.z), r = d.r * scale;
215:       if (x + r < 0 || x - r > W || y + r < 0 || y - r > H) continue;
216:       const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
217:       grad.addColorStop(0, d.color + '55'); grad.addColorStop(1, d.color + '00');
218:       ctx.fillStyle = grad; ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
219:     }
220:     // mar
221:     ctx.fillStyle = '#0b3b5b';
222:     ctx.fillRect(toX(690), 0, W, H);
223:     // ruas
224:     ctx.strokeStyle = '#687276'; ctx.lineWidth = 4;
225:     for (const rc of w.roadCoords) {
226:       const x = toX(rc), y = toY(rc);
227:       if (x > -50 && x < W + 50) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke(); }
228:       if (y > -50 && y < H + 50) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke(); }
229:     }
230:     ctx.strokeStyle = '#d8c14d'; ctx.lineWidth = 1;
231:     for (const rc of [0]) {
232:       const x = toX(rc), y = toY(rc);
233:       ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke();
234:       ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
235:     }
236:     // prédios
237:     ctx.fillStyle = 'rgba(15,22,25,.62)';
238:     for (const o of w.obstacles) {
239:       const x = toX((o.minX + o.maxX) / 2), y = toY((o.minZ + o.maxZ) / 2);
240:       if (x < -10 || x > W + 10 || y < -10 || y > H + 10) continue;
241:       const ww = Math.max(1, (o.maxX - o.minX) * scale), hh = Math.max(1, (o.maxZ - o.minZ) * scale);
242:       ctx.fillRect(x - ww / 2, y - hh / 2, ww, hh);
243:     }
244:     // POIs
245:     for (const poi of w.pois) {
246:       const x = toX(poi.x), y = toY(poi.z);
247:       if (x < 0 || x > W || y < 0 || y > H) continue;
248:       ctx.fillStyle = poi.type === 'gas' ? '#ff9a3d' : poi.type === 'hospital' ? '#fff' : '#54ff9d';
249:       ctx.beginPath(); ctx.arc(x, y, 3.2, 0, Math.PI * 2); ctx.fill();
250:     }
251:     // GPS
252:     const target = g.missions.target;
253:     if (target) {
254:       ctx.strokeStyle = '#5dff8a'; ctx.lineWidth = 3; ctx.setLineDash([6, 5]);
255:       ctx.beginPath(); ctx.moveTo(W / 2, H / 2); ctx.lineTo(toX(target.x), toY(target.z)); ctx.stroke();
256:       ctx.setLineDash([]);
257:       const tx = toX(target.x), ty = toY(target.z);
258:       if (tx > 5 && tx < W - 5 && ty > 5 && ty < H - 5) {
259:         ctx.fillStyle = '#ffd23c'; ctx.beginPath(); ctx.arc(tx, ty, 5, 0, Math.PI * 2); ctx.fill();
260:       } else {
261:         const ang = Math.atan2(ty - H / 2, tx - W / 2);
262:         const ex = W / 2 + Math.cos(ang) * (W / 2 - 10), ey = H / 2 + Math.sin(ang) * (H / 2 - 10);
263:         ctx.fillStyle = '#ffd23c'; ctx.beginPath(); ctx.arc(ex, ey, 5, 0, Math.PI * 2); ctx.fill();
264:       }
265:     }
266:     // polícia
267:     ctx.fillStyle = '#ff3045';
268:     for (const pc of g.police?.units || []) {
269:       const x = toX(pc.position.x), y = toY(pc.position.z);
270:       if (x > 0 && x < W && y > 0 && y < H) { ctx.beginPath(); ctx.arc(x, y, 3.4, 0, Math.PI * 2); ctx.fill(); }
271:     }
272:     // jogador
273:     ctx.save();
274:     ctx.translate(W / 2, H / 2);
275:     ctx.rotate(Math.PI - (p.inCar ? g.car.heading : p.yaw));
276:     ctx.fillStyle = '#61c9ff';
277:     ctx.shadowColor = '#39b7ff'; ctx.shadowBlur = 10;
278:     ctx.beginPath(); ctx.moveTo(0, -9); ctx.lineTo(6, 7); ctx.lineTo(0, 4); ctx.lineTo(-6, 7); ctx.closePath(); ctx.fill();
279:     ctx.restore();
280:     ctx.restore();
281:     // anel
282:     ctx.strokeStyle = 'rgba(255,255,255,.18)'; ctx.lineWidth = 2;
283:     ctx.beginPath(); ctx.arc(W / 2, H / 2, W / 2 - 2, 0, Math.PI * 2); ctx.stroke();
284:   }
