292:   drawBigMap() {
293:     const c = $('#bigmap');
294:     if (!c) return;
295:     const ctx = c.getContext('2d');
296:     const W = c.width, H = c.height;
297:     const g = this.game, w = g.world;
298:     const min = -700, max = 700;
299:     const toX = x => (x - min) / (max - min) * W;
300:     const toY = z => (z - min) / (max - min) * H;
301:     ctx.fillStyle = '#14251d'; ctx.fillRect(0, 0, W, H);
302:     // mar
303:     const seaGrad = ctx.createLinearGradient(toX(690), 0, W, 0);
304:     seaGrad.addColorStop(0, '#0a3d5e'); seaGrad.addColorStop(1, '#062537');
305:     ctx.fillStyle = seaGrad; ctx.fillRect(toX(690), 0, W - toX(690), H);
306:     ctx.fillStyle = 'rgba(80,170,200,.12)';
307:     for (let i = 0; i < 20; i++) ctx.fillRect(toX(690), i * 64, W, 2);
308:     // distritos
309:     for (const d of w.districts) {
310:       const x = toX(d.x), y = toY(d.z), r = d.r / 1400 * W;
311:       const grad = ctx.createRadialGradient(x, y, 0, x, y, r * 1.5);
312:       grad.addColorStop(0, d.color + '45'); grad.addColorStop(1, d.color + '00');
313:       ctx.fillStyle = grad; ctx.beginPath(); ctx.arc(x, y, r * 1.5, 0, Math.PI * 2); ctx.fill();
314:       ctx.fillStyle = 'rgba(240,248,255,.7)';
315:       ctx.font = 'bold 17px Arial'; ctx.textAlign = 'center';
316:       ctx.fillText(d.name, x, y - r - 6);
317:     }
318:     // ruas
319:     for (const rc of w.roadCoords) {
320:       ctx.strokeStyle = rc === 0 ? '#e8c94d' : '#70797c';
321:       ctx.lineWidth = rc === 0 ? 7 : 4;
322:       ctx.beginPath(); ctx.moveTo(toX(rc), 0); ctx.lineTo(toX(rc), H); ctx.stroke();
323:       ctx.beginPath(); ctx.moveTo(0, toY(rc)); ctx.lineTo(W, toY(rc)); ctx.stroke();
324:     }
325:     // prédios
326:     ctx.fillStyle = 'rgba(10,16,18,.55)';
327:     for (const o of w.obstacles) {
328:       const x = toX(o.minX), y = toY(o.minZ), ww = (o.maxX - o.minX) / 1400 * W, hh = (o.maxZ - o.minZ) / 1400 * H;
329:       ctx.fillRect(x, y, Math.max(2, ww), Math.max(2, hh));
330:     }
331:     // POIs
332:     for (const poi of w.pois) {
333:       const x = toX(poi.x), y = toY(poi.z);
334:       ctx.fillStyle = poi.type === 'gas' ? '#ff9a3d' : poi.type === 'hospital' ? '#ffffff' : '#54ff9d';
335:       ctx.beginPath(); ctx.arc(x, y, 6, 0, Math.PI * 2); ctx.fill();
336:       ctx.fillStyle = 'rgba(255,255,255,.8)'; ctx.font = '11px Arial'; ctx.textAlign = 'left';
337:       ctx.fillText(poi.name, x + 9, y + 4);
338:     }
339:     // polícia
340:     ctx.fillStyle = '#ff3045';
341:     for (const pc of g.police?.units || []) {
342:       ctx.beginPath(); ctx.arc(toX(pc.position.x), toY(pc.position.z), 6, 0, Math.PI * 2); ctx.fill();
343:     }
344:     // GPS
345:     const target = g.missions.target;
346:     if (target) {
347:       ctx.strokeStyle = '#5dff8a'; ctx.lineWidth = 5; ctx.setLineDash([12, 10]);
348:       ctx.beginPath();
349:       ctx.moveTo(toX(g.player.position.x), toY(g.player.position.z));
350:       ctx.lineTo(toX(target.x), toY(target.z)); ctx.stroke(); ctx.setLineDash([]);
351:       ctx.fillStyle = '#ffd23c'; ctx.beginPath(); ctx.arc(toX(target.x), toY(target.z), 9, 0, Math.PI * 2); ctx.fill();
352:     }
353:     // jogador
354:     ctx.save();
355:     ctx.translate(toX(g.player.inCar ? g.car.position.x : g.player.position.x), toY(g.player.inCar ? g.car.position.z : g.player.position.z));
356:     ctx.rotate(Math.PI - (g.player.inCar ? g.car.heading : g.player.yaw));
357:     ctx.fillStyle = '#61c9ff'; ctx.shadowColor = '#39b7ff'; ctx.shadowBlur = 18;
358:     ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(10, 12); ctx.lineTo(0, 7); ctx.lineTo(-10, 12); ctx.closePath(); ctx.fill();
359:     ctx.restore();
360:     // bússola
361:     ctx.fillStyle = 'rgba(4,10,20,.8)'; ctx.beginPath(); ctx.arc(W - 70, 70, 38, 0, Math.PI * 2); ctx.fill();
362:     ctx.strokeStyle = 'rgba(255,255,255,.3)'; ctx.stroke();
363:     ctx.fillStyle = '#fff'; ctx.font = 'bold 18px Arial'; ctx.textAlign = 'center'; ctx.fillText('N', W - 70, 58);
364:     ctx.fillStyle = '#61c9ff'; ctx.beginPath(); ctx.moveTo(W - 70, 62); ctx.lineTo(W - 64, 82); ctx.lineTo(W - 76, 82); ctx.closePath(); ctx.fill();
365:   }
