441:       for (let i = 0; i < 100; i++) {
442:         const base = CLOTHES_NAMES[i % CLOTHES_NAMES.length];
443:         const suffix = i >= CLOTHES_NAMES.length ? ` ${Math.floor(i / CLOTHES_NAMES.length) + 1}` : '';
444:         const color = CLOTH_COLORS[(i * 7 + 3) % CLOTH_COLORS.length];
445:         const price = 60 + (i % 12) * 35;
446:         items.push(`<button class="shop-item" data-buy-cloth="${i}" data-color="${color}" data-name="${base}${suffix}" data-price="${price}">
447:           <div class="swatch" style="--sw:linear-gradient(145deg,#${color.toString(16).padStart(6, '0')},#${((color >> 1) & 0x7f7f7f).toString(16).padStart(6, '0')})"></div>
448:           <b>${base}${suffix}</b><span>R$ ${price}</span><small>${i < 24 ? 'Destaque' : 'Coleção BR'}</small></button>`);
449:       }
450:       html = items.join('');
451:     } else if (type === 'barber') {
452:       html = [['Corte Social', 80], ['Corte Black', 120], ['Barba feita', 60], ['Corte + barba', 160], ['Pintura platinada', 250]].map(([n, p]) => `<button class="shop-item" data-service="barber" data-name="${n}" data-price="${p}"><div class="swatch" style="--sw:linear-gradient(145deg,#1b1b1b,#8f5b36)"></div><b>${n}</b><span>R$ ${p}</span><small>Barbearia</small></button>`).join('');
453:     } else if (type === 'gym') {
454:       html = [['Treino de força', 500, '+10 vida máxima'], ['Treino de velocidade', 650, '+corrida'], ['Treino completo', 1200, '+vida e velocidade']].map(([n, p, d]) => `<button class="shop-item" data-service="gym" data-name="${n}" data-price="${p}" data-desc="${d}"><div class="swatch" style="--sw:linear-gradient(145deg,#2c3a48,#8dff5a)"></div><b>${n}</b><span>R$ ${p}</span><small>${d}</small></button>`).join('');
455:     } else if (type === 'gun') {
456:       const guns = [['Pistola', 'pistola', 900, 60], ['Metralhadora', 'metralhadora', 3200, 180], ['Escopeta', 'escopeta', 2400, 24], ['Sniper', 'sniper', 6500, 12], ['Bazuca', 'bazuca', 15000, 4], ['Minigun', 'minigun', 28000, 500], ['Colete balístico', 'colete', 1200, 0], ['Mira laser', 'mira', 800, 0], ['Silenciador', 'silenciador', 950, 0]];
457:       html = guns.map(([n, id, p, ammo]) => `<button class="shop-item" data-service="gun" data-gun="${id}" data-name="${n}" data-price="${p}"><div class="swatch" style="--sw:linear-gradient(145deg,#3a4148,#c7a13d)"></div><b>${n}</b><span>R$ ${p.toLocaleString('pt-BR')}</span><small>${ammo ? '+ ' + ammo + ' munições' : 'Equipamento'}</small></button>`).join('');
458:     } else if (type === 'mechanic') {
459:       html = `<button class="shop-item" data-service="repair" data-name="Consertar carro" data-price="300"><div class="swatch" style="--sw:linear-gradient(145deg,#3c4b56,#e7e2d3)"></div><b>Consertar carro</b><span>R$ 300</span><small>Repara toda a lataria</small></button>
