20: function paletteAt(hour) {
21:   let a = PALETTES[0], b = PALETTES[PALETTES.length - 1];
22:   for (let i = 0; i < PALETTES.length - 1; i++) {
23:     if (hour >= PALETTES[i].h && hour <= PALETTES[i + 1].h) { a = PALETTES[i]; b = PALETTES[i + 1]; break; }
24:   }
25:   const t = clamp((hour - a.h) / Math.max(.001, b.h - a.h), 0, 1);
26:   const ease = t * t * (3 - 2 * t);
27:   return {
28:     top: new THREE.Color(a.top).lerp(new THREE.Color(b.top), ease),
29:     bottom: new THREE.Color(a.bottom).lerp(new THREE.Color(b.bottom), ease),
30:     sun: new THREE.Color(a.sun).lerp(new THREE.Color(b.sun), ease),
31:     hemi: new THREE.Color(a.hemi).lerp(new THREE.Color(b.hemi), ease),
32:     fog: new THREE.Color(a.fog).lerp(new THREE.Color(b.fog), ease),
33:     sunI: a.sunI + (b.sunI - a.sunI) * ease,
34:     hemiI: a.hemiI + (b.hemiI - a.hemiI) * ease,
35:     night: a.night + (b.night - a.night) * ease,
36:   };
