187:         axis, coord, dir, pos: rand(-580, 580), speed: rand(.7, 2.1), run: Math.random() < .14,
188:         state: Math.random() < .12 ? 'dance' : 'walk', phase: Math.random() * 6,
189:         x: 0, z: 0, color: pick(COLORS.shirt), skin: pick(COLORS.skin),
