201:   setDensity(f) {
202:     this.density = f;
203:     const n = Math.max(20, Math.floor(this.max * f));
204:     this.torsos.count = n; this.heads.count = n; this.legL.count = n; this.legR.count = n;
205:   }
206: 
207:   update(dt) {
208:     this.acc += dt;
209:     if (this.acc < .05) return;
210:     const step = this.acc; this.acc = 0;
211:     const active = Math.max(20, Math.floor(this.max * this.density));
212:     const dummy = new THREE.Object3D();
213:     for (let i = 0; i < this.max; i++) {
214:       const p = this.peds[i];
215:       if (i >= active) {
216:         dummy.position.set(0, -100, 0); dummy.scale.setScalar(0); dummy.updateMatrix();
217:         this.torsos.setMatrixAt(i, dummy.matrix); this.heads.setMatrixAt(i, dummy.matrix);
218:         this.legL.setMatrixAt(i, dummy.matrix); this.legR.setMatrixAt(i, dummy.matrix);
219:         continue;
220:       }
221:       if (p.state !== 'dance') {
222:         p.pos += p.dir * p.speed * (p.run ? 2.2 : 1) * step;
223:         if (p.pos > 590) p.pos = -590; if (p.pos < -590) p.pos = 590;
224:       } else {
225:         p.phase += step * 3;
226:       }
227:       let x, z;
228:       if (p.axis === 'x') {
229:         x = p.pos; z = p.coord + p.side * 9.2;
230:       } else {
231:         x = p.coord + p.side * 9.2; z = p.pos;
232:       }
233:       p.x = x; p.z = z;
234:       const bob = Math.abs(Math.sin(p.phase + (p.run ? 0 : 0))) * (p.run ? .11 : .05);
235:       const swing = Math.sin(p.phase * (p.run ? 2.3 : 1.6)) * (p.state === 'dance' ? .6 : .45);
236:       dummy.position.set(x, (.72 + bob) * p.scale, z);
237:       dummy.rotation.set(0, p.axis === 'x' ? (p.dir > 0 ? Math.PI / 2 : -Math.PI / 2) : (p.dir > 0 ? 0 : Math.PI), p.state === 'dance' ? Math.sin(p.phase * 2) * .18 : 0);
238:       dummy.scale.setScalar(p.scale);
239:       dummy.updateMatrix();
240:       this.torsos.setMatrixAt(i, dummy.matrix);
241:       dummy.position.set(x, (1.22 + bob) * p.scale, z);
242:       dummy.scale.setScalar(p.scale);
243:       dummy.updateMatrix();
244:       this.heads.setMatrixAt(i, dummy.matrix);
245:       // pernas
246:       const sideX = Math.cos(dummy.rotation.y) * .11, sideZ = -Math.sin(dummy.rotation.y) * .11;
247:       dummy.position.set(x + sideX, (.34 + bob) * p.scale, z + sideZ);
248:       dummy.rotation.set(swing, dummy.rotation.y, 0); dummy.updateMatrix();
249:       this.legL.setMatrixAt(i, dummy.matrix);
250:       dummy.position.set(x - sideX, (.34 + bob) * p.scale, z - sideZ);
251:       dummy.rotation.set(-swing, dummy.rotation.y, 0); dummy.updateMatrix();
252:       this.legR.setMatrixAt(i, dummy.matrix);
253:     }
254:     this.torsos.instanceMatrix.needsUpdate = true;
255:     this.heads.instanceMatrix.needsUpdate = true;
256:     this.legL.instanceMatrix.needsUpdate = true;
257:     this.legR.instanceMatrix.needsUpdate = true;
258:   }
