260:   nearby(x, z, radius = 12) {
261:     const arr = [];
262:     for (let i = 0; i < this.peds.length; i++) {
263:       const p = this.peds[i];
264:       if (p.x === undefined) continue;
265:       const d = Math.hypot(p.x - x, p.z - z);
266:       if (d < radius) arr.push({ ...p, index: i, dist: d });
267:     }
268:     return arr;
269:   }
270: }

