import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR', e.message); });
page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE', m.text()); } });
page.on('response', r => { if (r.status() >= 400) { errors.push(`HTTP ${r.status()} ${r.url()}`); console.log('HTTP', r.status(), r.url()); } });

await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForTimeout(800);
console.log('boot active', await page.locator('#boot-screen.active').count());
await page.locator('#powerBtn').click();
await page.waitForSelector('#profile-screen.active', { timeout: 20000 });
console.log('profile shown');
await page.screenshot({ path: join(out, '01-profile.png') });
await page.locator('.profile-card[data-profile="caio"]').click();
await page.waitForSelector('#dashboard.active', { timeout: 10000 });
await page.waitForTimeout(1200);
console.log('dashboard shown');
await page.screenshot({ path: join(out, '02-dashboard.png') });
await page.locator('#playGame').click();
await page.waitForSelector('body.in-game', { timeout: 10000 });
console.log('in game, waiting for engine');
await page.waitForFunction(() => window.app && window.app.game && window.app.game.active, null, { timeout: 60000 });
await page.waitForTimeout(3000);
console.log('game active', await page.evaluate(() => ({
  active: app.game.active,
  paused: app.game.paused,
  money: app.game.player.money,
  pos: app.game.player.position.toArray(),
  districts: app.game.world.districts.length,
  peds: app.game.world.peds.peds.length,
  traffic: app.game.world.traffic.cars.length,
  children: app.game.scene.children.length,
  mission: app.game.missions.active?.name,
  fatal: !!document.getElementById('fatal-error')
})));
await page.screenshot({ path: join(out, '03-game.png') });
// move forward and run
await page.keyboard.down('KeyW');
await page.keyboard.down('ShiftLeft');
await page.waitForTimeout(1600);
await page.keyboard.up('KeyW');
await page.keyboard.up('ShiftLeft');
await page.waitForTimeout(500);
console.log('after move', await page.evaluate(() => ({ pos: app.game.player.position.toArray(), speed: app.game.player.speed, health: app.game.player.health })));
await page.screenshot({ path: join(out, '04-move.png') });
// open map / close
await page.keyboard.press('KeyM');
await page.waitForTimeout(400);
console.log('map open', await page.locator('#map-screen:not(.hidden)').count());
await page.screenshot({ path: join(out, '05-map.png') });
await page.keyboard.press('KeyM');
// pause
await page.keyboard.press('Escape');
await page.waitForTimeout(300);
console.log('pause open', await page.locator('#pause-screen:not(.hidden)').count());
await page.screenshot({ path: join(out, '06-pause.png') });
// settings via pause
await page.locator('[data-pause="settings"]').click();
await page.waitForTimeout(300);
console.log('settings open', await page.locator('#settings-game:not(.hidden)').count());
await page.screenshot({ path: join(out, '07-settings.png') });
await page.selectOption('#qualitySelect', 'low');
await page.waitForTimeout(500);
console.log('quality', await page.evaluate(() => app.game.quality));
await page.locator('#settingsDone').click();
await page.waitForTimeout(200);
await page.locator('[data-pause="continue"]').click();
await page.waitForTimeout(500);
// phone
await page.keyboard.press('KeyP');
await page.waitForTimeout(300);
console.log('phone open', await page.locator('#phone-screen:not(.hidden)').count());
await page.screenshot({ path: join(out, '08-phone.png') });
await page.keyboard.press('KeyP');
// enter car (own car near spawn? player at 14,26, car at 24,42 dist ~18) so teleport near
await page.evaluate(() => { app.game.player.position.set(24, 0, 44); });
await page.waitForTimeout(300);
await page.keyboard.press('KeyE');
await page.waitForTimeout(600);
console.log('in car', await page.evaluate(() => ({ inCar: app.game.player.inCar, car: app.game.car.name })));
await page.screenshot({ path: join(out, '09-car.png') });
await page.keyboard.down('KeyW');
await page.waitForTimeout(1800);
await page.keyboard.up('KeyW');
console.log('car drive', await page.evaluate(() => ({ speed: app.game.car.speedKmh, pos: app.game.car.position.toArray(), fuel: app.game.car.fuel })));
await page.screenshot({ path: join(out, '10-drive.png') });
// attack / weapon
await page.evaluate(() => { app.game.equipWeapon('pistola'); });
await page.waitForTimeout(300);
await page.keyboard.press('KeyF');
await page.waitForTimeout(400);
console.log('weapon', await page.evaluate(() => ({ weapon: app.game.player.weapon, ammo: app.game.player.ammo.pistola, wanted: app.game.player.wanted })));
// cycle weather
await page.keyboard.press('KeyT');
await page.waitForTimeout(1000);
console.log('weather', await page.evaluate(() => app.game.world.weather));
await page.screenshot({ path: join(out, '11-rain.png') });
// cycle quality from HUD
await page.locator('#btnQuality').click();
await page.waitForTimeout(400);
console.log('quality2', await page.evaluate(() => app.game.quality));
// mobile viewport
await page.setViewportSize({ width: 844, height: 390 });
await page.waitForTimeout(600);
await page.screenshot({ path: join(out, '12-mobile.png') });
console.log('virtual controls visible', await page.evaluate(() => {
  const el = document.getElementById('virtual-controls');
  const r = el.getBoundingClientRect();
  return { display: getComputedStyle(el).display, rect: [r.x, r.y, r.width, r.height], mode: el.className };
}));
// back to ps5
await page.evaluate(() => app.game.exitToPS5());
await page.waitForTimeout(1000);
console.log('back to dashboard', await page.locator('#dashboard.active').count());
await page.screenshot({ path: join(out, '13-back.png') });
console.log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();

