const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForTimeout(500);
await page.evaluate(() => { app.ps5.selectProfile('caio'); app.ps5.launchGame(); });
await page.waitForFunction(() => window.app?.game?.active, null, { timeout: 60000 });
await page.waitForTimeout(2000);
console.log('fps measure', await page.evaluate(async () => {
  let frames = 0; const t0 = performance.now();
  await new Promise(resolve => {
    const tick = () => { frames++; if (performance.now() - t0 > 3000) resolve(); else requestAnimationFrame(tick); };
    requestAnimationFrame(tick);
  });
  return { frames, ms: performance.now() - t0, fps: frames / ((performance.now() - t0) / 1000) };
}));
// time individual systems
console.log('timings', await page.evaluate(() => {
  const g = app.game;
  const out = {};
  const time = (name, fn) => { const t = performance.now(); for (let i = 0; i < 20; i++) fn(); out[name] = ((performance.now() - t) / 20).toFixed(2); };
  time('world.update', () => g.world.update(.016, g.player.position));
  time('peds.update', () => g.world.peds.update(.05));
  time('traffic.update', () => g.world.traffic.update(.05, g.player.position));
  time('ui.updateHUD', () => g.ui.updateHUD());
  time('render', () => g.renderer.render(g.scene, g.camera));
  return out;
}));
console.log('quality', await page.evaluate(() => app.game.quality));
await page.evaluate(() => app.game.applyQuality('low'));
await page.waitForTimeout(500);
console.log('low timings', await page.evaluate(() => {
