import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(20000);
const errors = [];
page.on('pageerror', e => { errors.push('PAGEERROR ' + e.message); console.log('PAGEERROR', e.message); });
page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE ' + m.text()); console.log('CONSOLE', m.text()); } });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForTimeout(500);
await page.evaluate(() => { app.ps5.selectProfile('caio'); app.ps5.launchGame(); });
await page.waitForFunction(() => window.app?.game?.active, null, { timeout: 60000 });
await page.evaluate(() => app.game.applyQuality('low'));
await page.waitForTimeout(1200);
console.log('start', await page.evaluate(() => ({ mission: app.game.missions.active?.name, target: app.game.missions.target?.toArray(), quality: app.game.quality })));

// mission complete by teleport
await page.evaluate(() => {
  const t = app.game.missions.target;
  app.game.player.position.set(t.x, 0, t.z);
});
await page.waitForTimeout(1200);
console.log('mission completed', await page.evaluate(() => ({ completed: !!app.game.missions.active?.completed, money: app.game.player.money, nextIn: app.game.missions.index })));
await page.screenshot({ path: join(out, '30-mission-complete.png') });
await page.waitForTimeout(7000);
console.log('next mission', await page.evaluate(() => ({ index: app.game.missions.index, name: app.game.missions.active?.name, target: app.game.missions.target?.toArray() })));

// on-foot shooting
await page.evaluate(() => { app.game.player.inCar = false; app.game.car.group.visible = true; app.game.equipWeapon('pistola'); });
const ammoBefore = await page.evaluate(() => app.game.player.ammo.pistola);
await page.keyboard.press('KeyF');
await page.waitForTimeout(400);
console.log('shoot', await page.evaluate(a => ({ before: a, after: app.game.player.ammo.pistola, wanted: app.game.player.wanted }), ammoBefore));

// shop
await page.evaluate(() => app.game.openShop('clothing'));
await page.waitForTimeout(400);
console.log('shop', await page.evaluate(() => ({ open: !document.getElementById('shop-screen').classList.contains('hidden'), items: document.querySelectorAll('#shopGrid .shop-item').length, money: app.game.player.money })));
await page.screenshot({ path: join(out, '31-shop.png') });
const moneyBefore = await page.evaluate(() => app.game.player.money);
await page.locator('#shopGrid .shop-item').first().click();
await page.waitForTimeout(400);
console.log('bought', await page.evaluate(m => ({ before: m, after: app.game.player.money, clothes: app.game.player.clothes }), moneyBefore));
await page.locator('[data-close="shop"]').click();
await page.waitForTimeout(300);

// police escalation
await page.evaluate(() => app.game.police.setWanted(3));
await page.waitForTimeout(1500);
console.log('police', await page.evaluate(() => ({ wanted: app.game.player.wanted, units: app.game.police.units.length, heli: !!app.game.police.helicopter, siren: !!app.game.audio.sirenNodes })));
await page.screenshot({ path: join(out, '32-police.png') });
await page.evaluate(() => app.game.police.setWanted(0));
await page.waitForTimeout(400);

// death + respawn
await page.evaluate(() => app.game.player.takeDamage(999, 'teste'));
await page.waitForTimeout(500);
console.log('death', await page.evaluate(() => ({ dead: app.game.dead, screen: !document.getElementById('death-screen').classList.contains('hidden'), money: app.game.player.money })));
await page.screenshot({ path: join(out, '33-death.png') });
await page.locator('#respawnBtn').click();
await page.waitForTimeout(500);
console.log('respawn', await page.evaluate(() => ({ dead: app.game.dead, health: app.game.player.health, screenHidden: document.getElementById('death-screen').classList.contains('hidden') })));

// prison
await page.evaluate(() => app.game.onArrested());
await page.waitForTimeout(400);
console.log('prison', await page.evaluate(() => ({ inPrison: app.game.inPrison, screen: !document.getElementById('prison-screen').classList.contains('hidden'), ammo: app.game.player.ammo.pistola })));
await page.screenshot({ path: join(out, '34-prison.png') });
await page.locator('#prisonBtn').click();
await page.waitForTimeout(400);
console.log('leave prison', await page.evaluate(() => ({ inPrison: app.game.inPrison, health: app.game.player.health, pos: app.game.player.position.toArray() })));

// settings + quality via select (regression)
await page.evaluate(() => app.game.ui.openSettings());
await page.selectOption('#qualitySelect', 'medium');
await page.waitForTimeout(300);
console.log('quality via select', await page.evaluate(() => app.game.quality));
await page.locator('#settingsDone').click();

// control modes + mobile
await page.setViewportSize({ width: 844, height: 390 });
await page.waitForTimeout(500);
for (const mode of ['tutorial', 'dualsense', 'gta']) {
  await page.evaluate(m => app.game.input.setMode(m, true), mode);
  await page.waitForTimeout(400);
  console.log('mode', mode, await page.evaluate(() => {
    const vc = document.getElementById('virtual-controls');
    const ds = document.getElementById('dualsense-wrap');
    const tut = document.getElementById('tutorial-overlay');
