import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 844, height: 390 } });
page.setDefaultTimeout(20000);
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', m => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE', m.text()); } });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForTimeout(400);
console.log('mobile default quality', await page.evaluate(() => app.ps5.settings.quality));
await page.evaluate(() => { app.ps5.selectProfile('caio'); app.ps5.launchGame(); });
await page.waitForFunction(() => window.app?.game?.active, null, { timeout: 60000 });
await page.waitForTimeout(1500);
for (const mode of ['tutorial', 'dualsense', 'gta']) {
  await page.evaluate(m => app.game.input.setMode(m, true), mode);
  await page.waitForTimeout(500);
  console.log('mode', mode, await page.evaluate(() => {
    const ds = document.getElementById('dualsense-wrap');
    const tut = document.getElementById('tutorial-overlay');
    const gta = document.querySelector('.vc-gta-left');
    return {
      ui: document.getElementById('game-ui').className,
      ds: getComputedStyle(ds).display,
      tut: getComputedStyle(tut).display,
      gta: getComputedStyle(gta).display,
      dsRect: ds.getBoundingClientRect().toJSON()
    };
  }));
  await page.screenshot({ path: `/tmp/opencode/shots/40-${mode}.png` });
}
// jump via virtual cross, wait longer
await page.evaluate(() => app.game.input.setMode('gta', true));
await page.waitForTimeout(300);
const before = await page.evaluate(() => ({ y: app.game.player.position.y, vy: app.game.player.vy, paused: app.game.paused, active: app.game.active }));
await page.locator('#virtual-controls [data-action="cross"]').first().dispatchEvent('pointerdown', { pointerId: 1, pointerType: 'touch', bubbles: true });
await page.waitForTimeout(700);
await page.locator('#virtual-controls [data-action="cross"]').first().dispatchEvent('pointerup', { pointerId: 1, pointerType: 'touch', bubbles: true });
console.log('jump', before, await page.evaluate(() => ({ y: app.game.player.position.y, vy: app.game.player.vy })));
// virtual R2 in car
await page.evaluate(() => { app.game.player.position.set(24, 0, 44); });
await page.waitForTimeout(500);
await page.locator('#virtual-controls [data-action="triangle"]').first().dispatchEvent('pointerdown', { pointerId: 2, pointerType: 'touch', bubbles: true });
await page.locator('#virtual-controls [data-action="triangle"]').first().dispatchEvent('pointerup', { pointerId: 2, pointerType: 'touch', bubbles: true });
await page.waitForTimeout(800);
console.log('inCar virtual', await page.evaluate(() => ({ inCar: app.game.player.inCar, speed: app.game.car.speed })));
await page.locator('#virtual-controls [data-action="R2"]').first().dispatchEvent('pointerdown', { pointerId: 3, pointerType: 'touch', bubbles: true });
await page.waitForTimeout(1200);
await page.locator('#virtual-controls [data-action="R2"]').first().dispatchEvent('pointerup', { pointerId: 3, pointerType: 'touch', bubbles: true });
console.log('car accel virtual', await page.evaluate(() => ({ speed: app.game.car.speed, kmh: app.game.car.speedKmh, fuel: app.game.car.fuel })));
// fake gamepad
console.log('fake gamepad', await page.evaluate(() => {
  const buttons = Array.from({ length: 17 }, () => ({ pressed: false, value: 0 }));
  const pad = { connected: true, axes: [0, 0, 0, 0], buttons };
  navigator.getGamepads = () => [pad];
  app.game.input.gamepad = pad;
  app.game.input.prevButtons = [];
  app.game.player.inCar = false;
  buttons[0].pressed = true; buttons[0].value = 1;
  app.game.input.updateGamepad();
  buttons[0].pressed = false; buttons[0].value = 0;
  return { jump: app.game.input.jump, gamepad: !!app.game.input.gamepad };
}));
await page.waitForTimeout(300);
console.log('gamepad jump applied', await page.evaluate(() => ({ y: app.game.player.position.y, vy: app.game.player.vy })));
console.log('ERRORS', errors);
await browser.close();

