  let mesh = null;
  app.game.scene.traverse(o => {
    if (o.isMesh && o.material?.color && o.material.color.getHexString() === '8d8d86') mesh = o;
  });
  if (!mesh) return 'not found';
  const geo = mesh.geometry;
  const pos = geo.attributes.position;
  const idx = geo.index;
  let maxEdge = 0, bad = 0, examples = [];
  const triCount = (idx ? idx.count : pos.count) / 3;
  const get = i => idx ? idx.getX(i) : i;
  for (let t = 0; t < triCount; t++) {
    const a = get(t*3), b = get(t*3+1), c = get(t*3+2);
    const pa = [pos.getX(a), pos.getY(a), pos.getZ(a)];
    const pb = [pos.getX(b), pos.getY(b), pos.getZ(b)];
    const pc = [pos.getX(c), pos.getY(c), pos.getZ(c)];
    const d = (p,q) => Math.hypot(p[0]-q[0],p[1]-q[1],p[2]-q[2]);
    const e = Math.max(d(pa,pb), d(pb,pc), d(pc,pa));
    if (e > maxEdge) maxEdge = e;
    if (e > 20) { bad++; if (examples.length < 5) examples.push({ t, e, pa, pb, pc }); }
  }
  return { posCount: pos.count, triCount, maxEdge, bad, examples, bbox: geo.boundingBox };
}), null, 2));
await browser.close();

