input.content:
import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions });
for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844], ['landscape', 844, 390]]) {
  const page = await browser.newPage({ viewport: { width, height } });
  page.on('pageerror', e => console.log(name, 'PAGEERROR', e.message));
  page.on('console', m => { if (m.type() === 'error') console.log(name, 'CONSOLE', m.text()); });
  await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
  await page.waitForTimeout(700);
  await page.screenshot({ path: join(out, `70-${name}-boot.png`) });
  await page.evaluate(() => app.ps5.selectProfile('caio'));
  await page.waitForTimeout(900);
  await page.screenshot({ path: join(out, `71-${name}-dashboard.png`) });
  // store
