  openCreateProfile() {
    this.audio.click();
    this.openModal(`${this._header('NOVO PERFIL', 'Criar perfil', 'Monte seu jogador do jeito que quiser')}
      <div class="create-form" style="display:grid;grid-template-columns:1fr 1fr;gap:14px;max-width:620px">
