});
await page.waitForTimeout(500);
await step('exit car', async () => {
  await page.keyboard.press('e');
  await page.waitForTimeout(500);
  return page.evaluate(() => ({ inCar: app.game.player.inCar, playerVisible: app.game.player.root.visible }));
});

await step('attack', async () => {
  await page.keyboard.press('2');
  await page.waitForTimeout(100);
  await page.keyboard.press('f');
  await page.waitForTimeout(300);
  return page.evaluate(() => ({ weapon: app.game.player.weapon, ammo: app.game.player.ammo.pistola, wanted: app.game.player.wanted, effects: app.game.effects.length }));
});

await step('pause', async () => {
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  const vis = await page.locator('#pause-screen').isVisible();
  if (!vis) throw new Error('pause not visible');
  return { paused: await page.evaluate(() => app.game.paused) };
});
await page.screenshot({ path: '/tmp/opencode/shots/pause.jpg', type: 'jpeg', quality: 60 });
await page.keyboard.press('Escape');
await page.waitForTimeout(300);

await step('map', async () => {
  await page.keyboard.press('m');
  await page.waitForTimeout(300);
  const vis = await page.locator('#map-screen').isVisible();
  if (!vis) throw new Error('map not visible');
  const mapPainted = await page.evaluate(() => {
    const c = document.querySelector('#bigmap');
    const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    let n = 0; for (let i = 3; i < d.length; i += 4) if (d[i] > 0) n++;
    return n;
  });
  await page.keyboard.press('m');
  await page.waitForTimeout(200);
  return { mapPainted };
});

await step('weather + quality + radio', async () => {
  const before = await page.evaluate(() => ({ weather: app.game.world.weather, quality: app.game.quality, genre: app.audio.genre }));
  await page.keyboard.press('t');
  await page.waitForTimeout(150);
  await page.keyboard.press('F2');
  await page.waitForTimeout(300);
  await page.keyboard.press('v');
  await page.waitForTimeout(200);
  return page.evaluate(() => ({ before: { weather: app.game.world.weather, quality: app.game.quality }, after: { weather: app.game.world.weather, quality: app.game.quality, genre: app.audio.genre, shadows: app.game.renderer.shadowMap.enabled } }));
});

await step('settings', async () => {
  await page.keyboard.press('k');
  await page.waitForTimeout(300);
  const vis = await page.locator('#settings-game').isVisible();
  if (!vis) throw new Error('settings not visible');
  await page.locator('#qualitySelect').selectOption('high');
  await page.locator('#controlSelect').selectOption('tutorial');
  await page.waitForTimeout(300);
  return page.evaluate(() => ({ quality: app.game.quality, mode: app.game.input.mode }));
});
await page.locator('#settingsDone').click();
await page.waitForTimeout(300);

await step('shop', async () => {
  await page.evaluate(() => app.game.openShop('clothing'));
  await page.waitForTimeout(300);
  const vis = await page.locator('#shop-screen').isVisible();
  const items = await page.locator('#shopGrid button').count();
  if (!vis || !items) throw new Error('shop not populated');
  await page.screenshot({ path: '/tmp/opencode/shots/shop.jpg', type: 'jpeg', quality: 60 });
  await page.locator('#shop-screen .overlay-close').click();
  return { items };
});

await step('save + persistence', async () => {
  await page.evaluate(() => app.game.saveGame(true));
  const raw = await page.evaluate(() => localStorage.getItem('gta5br_save'));
  if (!raw) throw new Error('save missing');
  return JSON.parse(raw);
});

await step('pause menu -> PS5', async () => {
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  await page.locator('[data-pause="ps5"]').click();
  await page.waitForTimeout(500);
  return page.evaluate(() => ({ active: app.game.active, dashboard: document.querySelector('#dashboard').classList.contains('active') }));
});
await page.screenshot({ path: '/tmp/opencode/shots/back-dashboard.jpg', type: 'jpeg', quality: 60 });

await step('store', async () => {
  await page.locator('[data-menu="loja"]').click();
  await page.waitForTimeout(400);
  const open = await page.locator('#ps5-modal.open').count();
  const cards = await page.locator('#modalContent .store-card').count();
  const buy = await page.locator('[data-buy]').count();
  if (!open || !cards) throw new Error('store missing');
  await page.screenshot({ path: '/tmp/opencode/shots/store.jpg', type: 'jpeg', quality: 60 });
  return { cards, buy };
});
await step('buy + download', async () => {
  const id = await page.locator('[data-buy]').first().getAttribute('data-buy');
  await page.locator('[data-buy]').first().click();
  await page.waitForTimeout(1200);
  const state = await page.evaluate(id => ({ owned: app.ps5.owned.has(id), dl: app.ps5.downloads[id], text: document.querySelector(`[data-dltxt="${id}"]`)?.textContent }), id);
  if (!state.owned || !(state.dl > 0)) throw new Error('purchase/download failed ' + JSON.stringify(state));
  return state;
});
await page.locator('#modalClose').click();
await page.waitForTimeout(300);

for (const [menu, selector] of [['biblioteca', '.library-grid'], ['trofeus', '.trophy-grid'], ['amigos', '.friend-row'], ['config', '.settings-list'], ['midia', '.store-grid'], ['comunidade', '.store-grid']]) {
  await step('PS5 menu ' + menu, async () => {
    await page.locator(`[data-menu="${menu}"]`).click();
    await page.waitForTimeout(300);
    const n = await page.locator('#modalContent ' + selector).count();
    if (!n) throw new Error('content missing');
    await page.screenshot({ path: `/tmp/opencode/shots/menu-${menu}.jpg`, type: 'jpeg', quality: 55 });
    await page.locator('#modalClose').click();
    await page.waitForTimeout(200);
    return n;
  });
}

await step('sleep + wake', async () => {
  await page.locator('[data-menu="descanso"]').click();
  await page.waitForTimeout(300);
  const open = await page.locator('#sleep-screen.open').count();
  if (!open) throw new Error('sleep screen missing');
  await page.locator('#wakeBtn').click();
  await page.waitForTimeout(300);
  return { open, awake: await page.locator('#sleep-screen.open').count() === 0 };
});

console.log('ERRORS', JSON.stringify(errors, null, 2));
console.log('WARNINGS', JSON.stringify(logs.filter(l => l.startsWith('[warning]')), null, 2));
await browser.close();

