  keys: app.game.input.keys,
  pos: app.game.player.position.toArray(),
  camYaw: app.game.camYaw,
  coll: [[8,30],[8.5,30],[8,30.5],[8,29.5],[8.5,30.5]].map(([x,z])=>[x,z,app.game.world.collideCircle(x,z,.42)]),
  rootVisible: app.game.player.root.visible,
  tutorial: document.querySelector('#tutorial-overlay').className,
  uiMode: document.querySelector('#game-ui').className
})));
await page.keyboard.down('w');
await page.waitForTimeout(300);
console.log('during', await page.evaluate(()=>({
  keys: app.game.input.keys,
