  pos: app.game.player.position.toArray(), speed: app.game.player.speed,
  active: app.game.active, paused: app.game.paused, dead: app.game.dead,
  frame: app.game.renderer.info.render.frame
})));
await page.waitForTimeout(700);
console.log('after700', await page.evaluate(()=>({
  keys: app.game.input.keys, moveX: app.game.input.moveX, moveY: app.game.input.moveY,
  pos: app.game.player.position.toArray(), speed: app.game.player.speed,
  frame: app.game.renderer.info.render.frame
})));
await page.keyboard.up('w');
console.log('logs',logs);
await browser.close();

