22:   const roadMat = new THREE.MeshStandardMaterial({ color: 0x14171b, roughness: .58, metalness: .08, envMapIntensity: .5 });
23:   w.roadMat = roadMat;
24:   const walkMat = new THREE.MeshStandardMaterial({ color: 0x8d8d86, roughness: .9 });
25:   w.walkMat = walkMat;
26:   const markMat = new THREE.MeshBasicMaterial({ color: 0xf4f0d8 });
27:   const yellowMat = new THREE.MeshBasicMaterial({ color: 0xffcb35 });
28: 
29:   for (const c of w.roadCoords) {
30:     const width = c === 0 ? 24 : 14;
31:     addBox(roads, 1120, .06, width, 0, .02, c);
32:     addBox(roads, width, .06, 1120, c, .02, 0);
33:     addBox(walks, 1120, .16, 4, 0, .08, c + width / 2 + 2);
34:     addBox(walks, 1120, .16, 4, 0, .08, c - width / 2 - 2);
35:     addBox(walks, 4, .16, 1120, c + width / 2 + 2, .08, 0);
36:     addBox(walks, 4, .16, 1120, c - width / 2 - 2, .08, 0);
37:     // faixas amarelas centrais
38:     addBox(yellow, 1120, .035, .14, 0, .075, c - .18);
39:     addBox(yellow, 1120, .035, .14, 0, .075, c + .18);
40:     addBox(yellow, .14, .035, 1120, c - .18, .075, 0);
41:     addBox(yellow, .14, .035, 1120, c + .18, .075, 0);
42:     // faixas brancas tracejadas
43:     for (let t = -550; t < 550; t += 12) {
44:       addBox(marks, 4.5, .03, .16, t, .075, c - 4.2);
45:       addBox(marks, 4.5, .03, .16, t, .075, c + 4.2);
46:       addBox(marks, .16, .03, 4.5, c - 4.2, .075, t);
47:       addBox(marks, .16, .03, 4.5, c + 4.2, .075, t);
48:     }
49:   }
50:   // faixa de pedestre no centro
51:   for (let i = -5; i <= 5; i++) {
52:     addBox(marks, .7, .04, 7, i * 1.35, .08, 8.2);
53:     addBox(marks, .7, .04, 7, i * 1.35, .08, -8.2);
54:     addBox(marks, 7, .04, .7, 8.2, .08, i * 1.35);
55:     addBox(marks, 7, .04, .7, -8.2, .08, i * 1.35);
56:   }
57:   // faixas em outros cruzamentos principais
58:   for (const c of [-240, 240, 400, -400]) {
59:     for (let i = -4; i <= 4; i++) {
60:       addBox(marks, .6, .04, 6, i * 1.2, .08, c + 8.2);
61:       addBox(marks, .6, .04, 6, i * 1.2, .08, c - 8.2);
62:     }
63:   }
64:   const roadMesh = mergeToMesh(roads, roadMat, { castShadow: false });
65:   const walkMesh = mergeToMesh(walks, walkMat);
66:   const markMesh = mergeToMesh(marks, markMat, { castShadow: false });
67:   const yellowMesh = mergeToMesh(yellow, yellowMat, { castShadow: false });
68:   if (roadMesh) w.scene.add(roadMesh);
69:   if (walkMesh) w.scene.add(walkMesh);
70:   if (markMesh) w.scene.add(markMesh);
71:   if (yellowMesh) w.scene.add(yellowMesh);
72: 
73:   // placas de rua
74:   const signs = [
75:     ['AV. BRASIL', 20, 24, -18, .2], ['RUA DA PRAIA', 420, 24, 34, -.4],
76:     ['AV. CENTRAL', -180, 24, 20, 1.2], ['RUA DO MORRO', -260, 24, -220, .6],
77:     ['AV. INDUSTRIAL', 330, 24, -190, -.1], ['RUA JAPÃO', 160, 24, 290, 1.4],
78:     ['RODOVIA DO AEROPORTO', 40, 24, -380, 0], ['RUA DO COMÉRCIO', 120, 24, 190, .9]
79:   ];
80:   signs.forEach(([txt, x, y, z, ry]) => {
81:     const m = w.addSign(txt, x, y, z, ry, 8, 1.4, { bg: '#0d3a2a', color: '#fff', border: '#f4f4f4', font: 'bold 54px Arial', sub: 'BRASIL · CIDADE CAIO', subColor: '#bfe8cf' });
82:     m.material.depthTest = true;
83:   });
84: 
85:   // faixa BRASIL no chão da avenida central
86:   const flag = w.addSign('BRASIL', 0, .09, 58, 0, 18, 4.5, { bg: 'rgba(0,120,60,.9)', color: '#ffdf3d', border: '#ffdf3d', font: 'bold 100px Arial', sub: 'ORDEM E PROGRESSO', subColor: '#fff' });
87:   flag.rotation.x = -Math.PI / 2;
88:   flag.rotation.z = Math.PI;
89: }
