  detectPerformance() {
    const touch = matchMedia('(pointer: coarse)').matches || innerWidth < 900;
    if (!touch) return 'good';
    const mem = navigator.deviceMemory ? navigator.deviceMemory * 1024 * 1024 : 6 * 1024 * 1024 * 1024;
